select locate('a', name) as a, instr(name, 'a') as b, position('a' in name) as c, ascii(name) as d, ord(name) as e, bit_length(name) as f, octet_length(name) as g, strcmp(name, 'a') as h, name like 'a%' as i, name regexp 'a' as j, regexp_like(name, 'a') as k, regexp_replace(name, 'a', 'b') as l, regexp_substr(name, 'a') as m, regexp_instr(name, 'a') as o, soundex(name) as p, substring_index(name, 'a', 1) as q, find_in_set(name, 'a,b') as r, make_set(n, 'a', 'b') as s, export_set(n, 'y', 'n', ',', 4) as u, unhex(name) as v, from_base64(name) as w, char(n) as x, bin(n) as z, oct(n) as aa, conv(name, 10, 2) as ab, uncompress(raw) as ac, uncompressed_length(raw) as ad, inet_aton(name) as ae, inet_ntoa(n) as af, inet6_aton(name) as ag, is_ipv4(name) as ah, is_uuid(name) as ak, crc32(name) as al, name collate utf8mb4_bin as am, convert(name using latin1) as an, cast(name as char(2)) as ao, binary name as ap, weight_string(name) as aq from t where n between -1 and 2
